ALTER TABLE "BadmintonPackageCategory" ADD COLUMN "description" TEXT NOT NULL DEFAULT '';
ALTER TABLE "CourtBlock" ADD COLUMN "categoryCode" TEXT;
ALTER TABLE "CourtDateOverride" ADD COLUMN "categoryCodes" JSONB;
CREATE INDEX "CourtBlock_categoryCode_idx" ON "CourtBlock"("categoryCode");
CREATE INDEX "BadmintonEnrollment_packageId_status_expiryDate_idx" ON "BadmintonEnrollment"("packageId","status","expiryDate");
CREATE TABLE "CategoryMutationLock" ("id" INTEGER NOT NULL PRIMARY KEY);
INSERT INTO "CategoryMutationLock" ("id") VALUES (1);
DROP TRIGGER IF EXISTS "BadmintonPackageCategory_category_valid_insert";
DROP TRIGGER IF EXISTS "BadmintonPackageCategory_category_immutable";
CREATE TRIGGER "BadmintonPackageCategory_category_valid_insert" BEFORE INSERT ON "BadmintonPackageCategory" WHEN NEW."code" IS NOT NULL AND (NEW."code" NOT GLOB '[A-Z]*' OR NEW."code" GLOB '*[^A-Z0-9_]*' OR length(NEW."code") NOT BETWEEN 2 AND 40) BEGIN SELECT RAISE(ABORT,'Invalid badminton category'); END;
CREATE TRIGGER "BadmintonPackageCategory_category_immutable" BEFORE UPDATE OF "code" ON "BadmintonPackageCategory" WHEN (OLD."code" IS NOT NULL AND NEW."code" IS NOT OLD."code") OR (NEW."code" IS NOT NULL AND (NEW."code" NOT GLOB '[A-Z]*' OR NEW."code" GLOB '*[^A-Z0-9_]*' OR length(NEW."code") NOT BETWEEN 2 AND 40)) BEGIN SELECT RAISE(ABORT,'Badminton category is immutable'); END;
DROP TRIGGER IF EXISTS "BadmintonEnrollment_category_valid_insert";
DROP TRIGGER IF EXISTS "BadmintonEnrollment_category_immutable";
CREATE TRIGGER "BadmintonEnrollment_category_valid_insert" BEFORE INSERT ON "BadmintonEnrollment" WHEN NEW."categoryCode" IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM "BadmintonPackageCategory" WHERE "code"=NEW."categoryCode")) BEGIN SELECT RAISE(ABORT,'Invalid badminton category'); END;
CREATE TRIGGER "BadmintonEnrollment_category_immutable" BEFORE UPDATE OF "categoryCode" ON "BadmintonEnrollment" WHEN (OLD."categoryCode" IS NOT NULL AND NEW."categoryCode" IS NOT OLD."categoryCode") OR (NEW."categoryCode" IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM "BadmintonPackageCategory" WHERE "code"=NEW."categoryCode"))) BEGIN SELECT RAISE(ABORT,'Badminton category is immutable'); END;
