CREATE TRIGGER "BadmintonCheckIn_category_immutable" BEFORE UPDATE OF "categoryCode" ON "BadmintonCheckIn" WHEN (OLD."categoryCode" IS NOT NULL AND NEW."categoryCode" IS NOT OLD."categoryCode") OR (NEW."categoryCode" IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM "BadmintonPackageCategory" WHERE "code"=NEW."categoryCode"))) BEGIN SELECT RAISE(ABORT,'Badminton category is immutable'); END;
